def fill_cells(grid, max_iter=100):
    result = [row[:] for row in grid]
    changed = True
    for _ in range(max_iter):
        changed = False
        for r in range(1, len(result)-1):
            for c in range(1, len(result[0])-1):
                if result[r][c] == 0:
                    # Check all 4 neighbors
                    neigh = [result[r-1][c], result[r+1][c], result[r][c-1], result[r][c+1]]
